/**
 * financial-tracker/components/figma/ImageWithFallback.tsx
 *
 * Simple image component that renders an inline SVG fallback if the
 * original image fails to load. Useful for sketch/figma asset placeholders
 * where external image requests might fail during development.
 */
import React, { useState } from 'react'

const ERROR_IMG_SRC =
  'data:image/svg+xml;base64,'

/**
 * ImageWithFallback
 *
 * Renders an <img> element and falls back to a built-in inline SVG
 * image when loading fails. Maintains other `img` props via spread.
 * @param props - Standard image element props
 */
export function ImageWithFallback(props: React.ImgHTMLAttributes<HTMLImageElement>) {
  const [didError, setDidError] = useState(false)

  const handleError = () => {
    setDidError(true)
  }

  const { src, alt, style, className, ...rest } = props

  return didError ? (
    <div
      className={`inline-block bg-gray-100 text-center align-middle ${className ?? ''}`}
      style={style}
    >
      <div className="flex items-center justify-center w-full h-full">
        <img src={ERROR_IMG_SRC} alt="Error loading image" {...rest} data-original-url={src} />
      </div>
    </div>
  ) : (
    <img src={src} alt={alt} className={className} style={style} {...rest} onError={handleError} />
  )
}
